import React, { useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const ProductPage = () => {
  const { id2 } = useParams();
  const { addToCart, user } = useAuth();
  const [selectedImage, setSelectedImage] = useState(0);

  // Mock product data - replace with API call
  const product2 = {
    id: 1,
    name: '"',
    price: 12500,
    images: ['/images/луна 1.png', '/images/луна 2.png', '/images/луна 3.png', '/images/луна 4.png'],
    description: 'Элегантные серьги ручной работы из серебра 925 пробы с фианитами.',
    material: 'Серебро 925',
    length: '10 см',
    category: 'earrings'
  };

  const handleAddToCart = () => {
    addToCart(product);
    // Redirect to cart
    window.location.href = '/profile?tab=cart';
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      {/* Breadcrumbs */}
      <nav className="text-sm text-gray-500 mb-8">
        <Link to="/" className="hover:text-gold-600">Главная</Link>
        <span className="mx-2">›</span>
        <Link to="/catalog" className="hover:text-gold-600">Каталог</Link>
        <span className="mx-2">›</span>
        <span className="capitalize">{product.category}</span>
        <span className="mx-2">›</span>
        <span>{product.name}</span>
      </nav>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
        {/* Images */}
        <div>
          <div className="mb-4">
            <img 
              src={product.images[selectedImage]} 
              alt={product.name}
              className="w-full h-96 object-cover rounded-lg"
            />
          </div>
          <div className="grid grid-cols-4 gap-2">
            {product.images.map((image, index) => (
              <button
                key={index}
                onClick={() => setSelectedImage(index)}
                className={`border-2 rounded ${
                  selectedImage === index ? 'border-gold-600' : 'border-transparent'
                }`}
              >
                <img 
                  src={image} 
                  alt={`${product.name} ${index + 1}`}
                  className="w-full h-20 object-cover rounded"
                />
              </button>
            ))}
          </div>
        </div>

        {/* Product Info */}
        <div>
          <h1 className="text-3xl font-serif font-bold mb-4">{product.name}</h1>
          <p className="text-2xl text-gold-600 font-bold mb-6">{product.price.toLocaleString()} ₽</p>

          <div className="space-y-3 mb-6">
            <div className="flex items-center">
              <span className="w-6">☐</span>
              <span className="ml-2">Материал: {product.material}</span>
            </div>
            <div className="flex items-center">
              <span className="w-6">☐</span>
              <span className="ml-2">Длина: {product.length}</span>
            </div>
          </div>

          <button
            onClick={handleAddToCart}
            className="w-full bg-gold-600 hover:bg-gold-700 text-white py-3 rounded-lg font-semibold mb-4"
          >
            ДОБАВИТЬ В КОРЗИНУ
          </button>

          <button className="w-full border border-gold-600 text-gold-600 hover:bg-gold-50 py-3 rounded-lg font-semibold flex items-center justify-center">
            ❤️ ИЗБРАННОЕ
          </button>

          {/* Description */}
          <div className="mt-8">
            <h3 className="text-xl font-semibold mb-4">✔️ Описание</h3>
            <p className="text-gray-600 leading-relaxed">{product.description}</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductPage2;
